/**
 * Model Card / Model Registry — tool-local actions.
 *
 * Category: AI / LLM PM (squad S12a, Wave 4 — CRUD-backed tools)
 * Tool:     Model registry with cost, latency, status, evals
 *           (status lifecycle: experimental → evaluation → production
 *           → deprecated).
 *
 * Agent surface: tool.model_card.*
 * Backing CRUD : workspace.model.* (auto-generated by
 *                defineCrudActions in src/lib/actions/workspace/index.ts).
 *
 * ─── CRUD-BACKED tool pattern (vs the calculator pattern) ────────────
 * Model entries are record-keeping rows: generic create / list / update /
 * delete already exist via the auto-generated workspace.model.* surface.
 * This file only adds VERBS THE AGENT WANTS TO SPEAK in the model
 * registry's domain vocabulary:
 *
 *   1. list_state                  — read all model entries with stats:
 *                                    {byStatus, byVendor, totalCount,
 *                                    items: sorted by status then name}.
 *                                    Lets the agent plan ("what models are
 *                                    in production? which vendors do we
 *                                    use?") in one round-trip.
 *   2. compute_cost_estimate       — read, PURE: given
 *                                    {model: ModelEntry-shaped,
 *                                    inputTokens, outputTokens} return
 *                                    {inputCostUsd, outputCostUsd,
 *                                    totalUsd, costPer1kInput,
 *                                    costPer1kOutput}. Agents can estimate
 *                                    spend before committing — no
 *                                    mcpHandler because there's no
 *                                    server-side state to consult, the
 *                                    inputs ARE the state.
 *   3. promote_to_production       — write: set status="production" on
 *                                    the target AND auto-demote any OTHER
 *                                    production model from the same vendor
 *                                    to "deprecated" (single-production-
 *                                    per-vendor invariant, analogous to
 *                                    prompt-registry's per-name invariant).
 *                                    requiresConfirmation defaults to true.
 *   4. deprecate                   — write: set status="deprecated";
 *                                    append the reason to notes if
 *                                    provided. Idempotent.
 *   5. record_eval                 — write: update evalScore (0..1).
 *                                    Used by the llm-eval-tracker agent
 *                                    to write back a model's rolling
 *                                    eval score.
 *
 * ─── PRODUCTION-PER-VENDOR INVARIANT ─────────────────────────────────
 * The in-app UI doesn't stop a user from marking BOTH "anthropic/claude-x"
 * and "anthropic/claude-y" as `production` simultaneously. For agent
 * usage we want a stronger invariant: at most one production model per
 * vendor. `promote_to_production` enforces this by demoting any existing
 * production peer (same vendor, different id) to `deprecated` before
 * promoting the target.
 *
 * ─── ID NAMING ───────────────────────────────────────────────────────
 * Namespace is `tool.model_card` (snake_case to round-trip through
 * Anthropic's tool-name munging). The user-facing route is `/model-card`
 * (kebab-case), but kebab is illegal in tool ids.
 *
 * Entity kind for server-store is `workspace:model` (single-word entity,
 * no asymmetry between kindFromToolId("workspace.model") and the
 * browser-side registerCollection("model", "models") registration).
 * ─────────────────────────────────────────────────────────────────────
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import {
  serverListEntities,
  serverGetEntity,
  serverUpsertEntity,
  serverBulkUpsertEntities,
} from "../server-store";
import type { ModelEntry } from "@/lib/stores/workspace-types";

/** Server-side entity kind. Matches kindFromToolId("workspace.model")
 *  used by the auto-generated CRUD in src/lib/actions/workspace/index.ts,
 *  so reads/writes here line up byte-for-byte with the generic surface.
 *  Browser-side sync registers as "workspace:model" — no asymmetry
 *  because "model" is a single word (cf. DACI / RACI). */
const KIND_MODEL = "workspace:model";

/** Closed enum of valid model lifecycle statuses. Matches the literal
 *  union in workspace-types.ts:ModelEntry.status verbatim — Zod will
 *  reject anything else at the boundary. Sort order in list_state
 *  follows this array (production first, deprecated last) so an agent
 *  scanning the response top-to-bottom hits the live models first. */
const STATUSES = ["production", "evaluation", "experimental", "deprecated"] as const;
type Status = (typeof STATUSES)[number];

/** Numeric order for status — lower comes first in list_state sort.
 *  Matches the STATUSES array order so the literal `production` rows
 *  bubble to the top and `deprecated` sinks to the bottom. */
const STATUS_ORDER: Record<Status, number> = {
  production: 0,
  evaluation: 1,
  experimental: 2,
  deprecated: 3,
};

const ws = () => useWorkspaceStore.getState();

/** Shape of the summary returned by list_state. byStatus + byVendor are
 *  fully-initialised buckets (zeros included) so the agent can read
 *  `result.byStatus.production` without an existence check even on an
 *  empty workspace. */
interface ListStateResult {
  totalCount: number;
  byStatus: Record<Status, number>;
  byVendor: Record<string, number>;
  items: ModelEntry[];
}

/** Build the {totalCount, byStatus, byVendor, items} response. Kept as
 *  a single helper so the browser-path and MCP-path responses are
 *  guaranteed identical — drift would mean an agent gets different
 *  shapes depending on whether it's invoked from chat or over MCP. */
function summarize(items: ModelEntry[]): ListStateResult {
  const byStatus: Record<Status, number> = {
    production: 0,
    evaluation: 0,
    experimental: 0,
    deprecated: 0,
  };
  const byVendor: Record<string, number> = {};
  for (const m of items) {
    if (m.status in byStatus) byStatus[m.status] += 1;
    byVendor[m.vendor] = (byVendor[m.vendor] ?? 0) + 1;
  }
  // Sort: status order (production first), then name alphabetically.
  // Stable name order means consecutive calls return the same sequence —
  // agents that diff list_state across calls won't see noise.
  const sorted = [...items].sort((a, b) => {
    const sa = STATUS_ORDER[a.status] ?? 99;
    const sb = STATUS_ORDER[b.status] ?? 99;
    if (sa !== sb) return sa - sb;
    return a.name.localeCompare(b.name);
  });
  return {
    totalCount: items.length,
    byStatus,
    byVendor,
    items: sorted,
  };
}

// ──────── tool.model_card.list_state ────────
// Snapshot + summary. The agent's most common opening question is "what
// models do we have, and what state are they in?" — returning items +
// byStatus + byVendor + totalCount in one round-trip avoids a follow-up
// reduce on the agent's end.
registry.register({
  id: "tool.model_card.list_state",
  toolId: "tool.model_card",
  name: "list_state",
  category: "read",
  description:
    "List all model entries in the workspace with rollup stats. Returns {totalCount, byStatus: {production, evaluation, experimental, deprecated}, byVendor: {[vendor]: count}, items: ModelEntry[] sorted by status (production first) then name}.",
  paramsSchema: z.object({}),
  handler: async () => {
    const items = ws().models ?? [];
    return summarize(items);
  },
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<ModelEntry>(ctx.userId, KIND_MODEL);
    return summarize(items);
  },
});

// ──────── tool.model_card.compute_cost_estimate ────────
// PURE read — no workspace state, no mcpHandler. Given a model-shaped
// object (typically passed in directly so the agent can what-if without
// modifying the registry) and a token volume, return a cost breakdown.
//
// Validates token counts are non-negative; treats missing per-1k rates
// as 0 (the model entry didn't specify a price for that side, so we
// can't estimate a cost — surface it as 0 + ensure the agent can detect
// the missing-rate case via the returned costPer1k* fields).
const ModelEntryShape = z.object({
  id: z.string().optional(),
  name: z.string(),
  vendor: z.string(),
  inputCostPer1k: z.number().nonnegative().optional(),
  outputCostPer1k: z.number().nonnegative().optional(),
  contextWindow: z.number().nonnegative().optional(),
  latencyP50Ms: z.number().nonnegative().optional(),
  latencyP95Ms: z.number().nonnegative().optional(),
  evalScore: z.number().min(0).max(1).optional(),
  status: z.enum(STATUSES).optional(),
  notes: z.string().optional(),
});
registry.register({
  id: "tool.model_card.compute_cost_estimate",
  toolId: "tool.model_card",
  name: "compute_cost_estimate",
  category: "read",
  description:
    "Pure cost estimator: given a model-shaped object (with inputCostPer1k/outputCostPer1k USD rates) and token counts, return {inputCostUsd, outputCostUsd, totalUsd, costPer1kInput, costPer1kOutput}. Missing per-1k rates are treated as 0 — check the returned costPer1k* values to detect uninitialised pricing. Useful for the agent to estimate spend before committing to a model.",
  paramsSchema: z.object({
    model: ModelEntryShape,
    inputTokens: z.number().nonnegative(),
    outputTokens: z.number().nonnegative(),
  }),
  handler: async (params) => {
    const costPer1kInput = params.model.inputCostPer1k ?? 0;
    const costPer1kOutput = params.model.outputCostPer1k ?? 0;
    const inputCostUsd = (params.inputTokens / 1000) * costPer1kInput;
    const outputCostUsd = (params.outputTokens / 1000) * costPer1kOutput;
    return {
      inputCostUsd,
      outputCostUsd,
      totalUsd: inputCostUsd + outputCostUsd,
      costPer1kInput,
      costPer1kOutput,
    };
  },
  // No mcpHandler — pure function, the inputs ARE the state. Falling
  // back to handler is exactly what we want on the MCP path.
});

// ──────── tool.model_card.promote_to_production ────────
// Set status="production" on the target AND auto-demote any OTHER
// model from the same vendor currently in production, enforcing the
// single-production-per-vendor invariant the in-app UI does not.
//
// requiresConfirmation defaults to true for `write` — this is a real
// production cut-over and the agent should pause before executing it.
registry.register({
  id: "tool.model_card.promote_to_production",
  toolId: "tool.model_card",
  name: "promote_to_production",
  category: "write",
  description:
    "Promote a model to status='production'. Auto-demotes any OTHER model from the same vendor currently in production to 'deprecated' (enforces single-production-per-vendor invariant). Returns {promoted: false} when the id is unknown; otherwise {promoted: true, demoted: string[] (ids that were auto-demoted)}.",
  paramsSchema: z.object({
    id: z.string(),
  }),
  handler: async (params) => {
    const all = ws().models ?? [];
    const target = all.find((m) => m.id === params.id);
    if (!target) return { promoted: false, demoted: [] as string[] };
    const upsert = ws().upsertModel;
    // Demote any OTHER model of the same vendor currently in production.
    // Filtering by id !== target.id covers the no-op case where the
    // target is itself already in production — we don't want to demote
    // it then re-promote it (same row, redundant write).
    const toDemote = all.filter(
      (m) => m.vendor === target.vendor && m.status === "production" && m.id !== target.id
    );
    for (const d of toDemote) {
      upsert({ ...d, status: "deprecated" });
    }
    upsert({ ...target, status: "production" });
    return { promoted: true, demoted: toDemote.map((d) => d.id) };
  },
  mcpHandler: async (params, ctx) => {
    const target = await serverGetEntity<ModelEntry>(ctx.userId, KIND_MODEL, params.id);
    if (!target) return { promoted: false, demoted: [] as string[] };
    // serverGetEntity fetches one row by id; for the demote step we
    // need ALL rows sharing the same vendor. user_entities has no
    // payload-field index, so list + filter is the right shape.
    const all = await serverListEntities<ModelEntry>(ctx.userId, KIND_MODEL);
    const toDemote = all.filter(
      (m) => m.vendor === target.vendor && m.status === "production" && m.id !== target.id
    );
    const writes: ModelEntry[] = toDemote.map((d) => ({
      ...d,
      status: "deprecated" as const,
    }));
    writes.push({ ...target, status: "production" as const });
    // Bulk upsert in one round-trip. The browser-path doesn't need this
    // optimisation (local Zustand mutation), but on MCP each
    // serverUpsertEntity is a network hop.
    await serverBulkUpsertEntities<ModelEntry>(ctx.userId, KIND_MODEL, writes);
    return { promoted: true, demoted: toDemote.map((d) => d.id) };
  },
});

// ──────── tool.model_card.deprecate ────────
// Set status="deprecated", optionally appending a reason to notes.
// Idempotent — calling on an already-deprecated model is a no-op
// (returns {updated: false}) so an LLM-driven "retire all v1.x"
// sweep won't repeatedly write the same row.
//
// requiresConfirmation:false — deprecating is reversible (set the
// status back via workspace.model.update) and the natural agent
// phrasing — "deprecate the old model" — would be unbearable to confirm
// one-by-one across a batch.
registry.register({
  id: "tool.model_card.deprecate",
  toolId: "tool.model_card",
  name: "deprecate",
  category: "write",
  requiresConfirmation: false,
  description:
    "Mark a model as status='deprecated'. Optionally appends a reason to notes. Idempotent — returns {updated: false} when the model is already deprecated OR the id is unknown.",
  paramsSchema: z.object({
    id: z.string(),
    reason: z
      .string()
      .max(500)
      .optional()
      .describe("Optional human-readable reason; appended to the model's notes."),
  }),
  handler: async (params) => {
    const items = ws().models ?? [];
    const current = items.find((m) => m.id === params.id);
    if (!current) return { updated: false };
    if (current.status === "deprecated" && !params.reason) {
      // Already deprecated and no new note to record — true no-op.
      return { updated: false };
    }
    const nextNotes = appendReason(current.notes, params.reason);
    ws().upsertModel({ ...current, status: "deprecated", notes: nextNotes });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<ModelEntry>(ctx.userId, KIND_MODEL, params.id);
    if (!current) return { updated: false };
    if (current.status === "deprecated" && !params.reason) {
      return { updated: false };
    }
    const nextNotes = appendReason(current.notes, params.reason);
    await serverUpsertEntity<ModelEntry>(ctx.userId, KIND_MODEL, {
      ...current,
      status: "deprecated",
      notes: nextNotes,
    });
    return { updated: true };
  },
});

/** Append a deprecation reason to existing notes in a way that
 *  preserves prior history. No reason → return existing notes unchanged
 *  (so the no-op path is byte-identical when reason is omitted). */
function appendReason(
  existing: string | undefined,
  reason: string | undefined
): string | undefined {
  if (!reason) return existing;
  const tag = `[deprecated] ${reason}`;
  if (!existing || existing.trim() === "") return tag;
  return `${existing}\n${tag}`;
}

// ──────── tool.model_card.record_eval ────────
// Set evalScore on a model. The surface is intentionally minimal — an
// LLM-eval agent's typical loop is "run eval → write score back" and we
// don't want it to have to read-merge-write the whole row.
//
// requiresConfirmation:false — overwriting an eval score is
// non-destructive in any load-bearing sense (the previous score is a
// metric, not state the user relies on).
registry.register({
  id: "tool.model_card.record_eval",
  toolId: "tool.model_card",
  name: "record_eval",
  category: "write",
  requiresConfirmation: false,
  description:
    "Record an evaluation score (0..1) on a model entry. Overwrites any prior score. Returns {updated: false} when the id is unknown.",
  paramsSchema: z.object({
    id: z.string(),
    evalScore: z
      .number()
      .min(0)
      .max(1)
      .describe("Evaluation score in [0, 1]; conventionally displayed as a percentage in the UI"),
  }),
  handler: async (params) => {
    const items = ws().models ?? [];
    const current = items.find((m) => m.id === params.id);
    if (!current) return { updated: false };
    ws().upsertModel({ ...current, evalScore: params.evalScore });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<ModelEntry>(ctx.userId, KIND_MODEL, params.id);
    if (!current) return { updated: false };
    await serverUpsertEntity<ModelEntry>(ctx.userId, KIND_MODEL, {
      ...current,
      evalScore: params.evalScore,
    });
    return { updated: true };
  },
});
